-- Nexmark q22 on clink, BLACKHOLE sink variant. URL directory extraction:
-- string splitting, per record.
-- GENERATED by queries/gen_queries.py from the single cross-engine
-- definition. Edit that file, not this one.
CREATE TABLE bid (auction BIGINT, bidder BIGINT, price BIGINT, channel VARCHAR, url VARCHAR, datetime BIGINT)
  WITH (connector='kafka', format='json', brokers='__BROKERS__', topic='nx-bid',
        group_id='clink-q22bh-bid', auto_offset_reset='earliest',
        event_time_column='datetime', watermark_lag_ms='4001');
CREATE TABLE sink_q22 (auction BIGINT, bidder BIGINT, price BIGINT, dir VARCHAR) WITH (connector='blackhole');
INSERT INTO sink_q22
SELECT auction, bidder, price, SPLIT_INDEX(url, '/', 3) AS dir FROM bid;
